d712d179411c0498df3edbee9f4afd0cfc23d78b.query:
query ConditionalBook($id: ID!, $show: Boolean!) {
  book(id: $id) {
    id
    ... on Book @include(if: $show) {
      title
    }
  }
}

f21492db5d6f9db6bc4e08b25ef9341c53cc05d9.query:
query ReadBook($id: ID!) {
  selected: book(id: $id) {
    ...BookSummary
    published
    authors
  }
}

fragment BookSummary on Book {
  id
  title
}

cbdb1dc4a52fe6ff032666f5181a4c81b79ae5d2.query:
query SearchCatalog($filter: BookFilter) {
  search(filter: $filter) {
    __typename
    ... on Book {
      ...BookSummary
    }
    ... on Author {
      id
      name
    }
  }
}

fragment BookSummary on Book {
  id
  title
}

4dc0c7a1c48b239c6aece9855c409d8ad380a278.query:
mutation RenameBook($id: ID!, $title: String!) {
  renameBook(id: $id, title: $title) {
    ...BookSummary
  }
}

fragment BookSummary on Book {
  id
  title
}

1756c228d7e67c765cc64da85b6d9973a1c7f0c2.query:
query LookupEntry($id: ID!) {
  entry(id: $id) {
    __typename
    id
    ... on Book {
      title
    }
    ... on Author {
      name
    }
  }
}

012707a0126914ef7af2485d28fe8973a6de094d.query:
query ParityChecks($id: ID!, $show: Boolean!) {
  book(id: $id) {
    id
  }
  book(id: $id) @include(if: $show) {
    title
  }
  guaranteed: book(id: $id) {
    title @include(if: true)
    hidden: title @skip(if: true)
  }
}

b92af410f2040902356233d8dae2c520a2332124.query:
query ParityFragments {
  search {
    __typename
    ...SearchKeys
  }
}

fragment SearchKeys on SearchHit {
  __typename
  ... on Book {
    id
  }
  ... on Author {
    name
  }
}

9da9d7c09668fc07f36b10451a869c55b02791e6.query:
query InspectSchema($name: String!) {
  __schema {
    queryType {
      name
      kind
    }
    directives {
      name
      locations
      isRepeatable
    }
  }
  __type(name: $name) {
    name
    kind
    fields(includeDeprecated: true) {
      name
      type {
        kind
        name
        ofType {
          name
          kind
        }
      }
    }
  }
}
